from common import P

CHAPTERS = [
dict(id="homophones", el="Ομόηχες λέξεις", title="Same sound, different spelling", level="A2–C1",
 intro=["Greek has five ways to write the sound *i* (ι, η, υ, ει, οι) and two each for *o* (ο, ω) and *e* (ε, αι). Words that sound the same are told apart only in writing. You will hear them in dictation and have to spell them in the writing paper, so learn each with a short phrase."],
 pairs=[
  P([("τοίχος", "wall (of a room or house)"), ("τείχος", "city wall, rampart")],
    "**ο τοίχος** is an ordinary wall; **το τείχος** a fortification (τα τείχη της Πόλης *the walls of Constantinople*, το Σινικό Τείχος *the Great Wall of China*). Different gender too.",
    ex=[("Κρέμασα τον πίνακα στον τοίχο.", "I hung the picture on the wall."), ("Τα βυζαντινά τείχη της Θεσσαλονίκης.", "The Byzantine walls of Thessaloniki.")],
    gaps=[("Τα παιδιά έγραψαν συνθήματα στον ___.", "τοίχο", ["τείχο"], "The children wrote slogans on the wall."), ("Οι Οθωμανοί πέρασαν τα ___ το 1453.", "τείχη", ["τοίχους"], "The Ottomans breached the walls in 1453.")]),
  P([("λαιμός", "neck, throat"), ("λιμός", "famine"), ("λοιμός", "plague")],
    "Three words all pronounced *limós*: **λαιμός** *neck, throat* (με πονάει ο λαιμός μου *I have a sore throat*), **λιμός** *famine*, **λοιμός** *plague, pestilence* (λοιμώξεις *infections*).",
    ex=[("Φόρα ένα κασκόλ, θα πονέσει ο λαιμός σου.", "Wear a scarf, or your throat will hurt."), ("Ο μεγάλος λιμός του 1941–42 στην Αθήνα.", "The great famine of 1941–42 in Athens.")],
    gaps=[("Έχω πυρετό και πονάει ο ___ μου.", "λαιμός", ["λιμός", "λοιμός"], "I have a temperature and my throat hurts."), ("Κατά την Κατοχή ο ___ σκότωσε χιλιάδες ανθρώπους.", "λιμός", ["λαιμός", "λοιμός"], "During the Occupation the famine killed thousands of people.")]),
  P([("κλείνω", "close, shut"), ("κλίνω", "decline (a noun), conjugate; lean")],
    "**κλείνω** is *close* (κλείσε την πόρτα); **κλίνω** is *inflect* in grammar and *lean, tend* (κλίνω προς *I lean towards*). Hence **η κλίση** *declension; slope; inclination*.",
    ex=[("Κλείσε το παράθυρο, κάνει κρύο.", "Close the window, it's cold."), ("Πώς κλίνεται το ουσιαστικό «κρέας»;", "How is the noun κρέας declined?")],
    gaps=[("Τα μαγαζιά ___ στις εννιά.", "κλείνουν", ["κλίνουν"], "The shops close at nine."), ("Τα ουδέτερα σε -μα ___ όπως το «όνομα».", "κλίνονται", ["κλείνονται"], "Neuters in -μα decline like όνομα.")]),
  P([("πείρα", "experience"), ("πήρα", "I took, I got")],
    "**η πείρα** is *experience* (επαγγελματική πείρα); **πήρα** is the aorist of παίρνω: *I took, I got, I bought*. Also **η πείρα** vs **το πείραμα** *experiment* (same root).",
    ex=[("Έχει μεγάλη πείρα στις πωλήσεις.", "She has a lot of sales experience."), ("Πήρα ένα καινούργιο κινητό.", "I got a new mobile.")],
    gaps=[("Ζητάμε υπάλληλο με ___ στον τουρισμό.", "πείρα", ["πήρα"], "We're looking for an employee with experience in tourism."), ("Χθες ___ τηλέφωνο τη μητέρα μου.", "πήρα", ["πείρα"], "Yesterday I phoned my mother.")]),
  P([("λύρα", "lyre; Cretan fiddle"), ("λίρα", "pound (currency); gold sovereign")],
    "**η λύρα** is the musical instrument (κρητική λύρα); **η λίρα** a currency (αγγλική λίρα *pound sterling*) or a gold coin (χρυσή λίρα, the traditional christening and wedding gift).",
    ex=[("Ο παππούς παίζει λύρα στα πανηγύρια.", "Grandad plays the lyra at village festivals."), ("Του χάρισαν μια χρυσή λίρα στη βάφτιση.", "They gave him a gold sovereign at his christening.")],
    gaps=[("Η κρητική ___ συνοδεύει τις μαντινάδες.", "λύρα", ["λίρα"], "The Cretan lyra accompanies mantinades.")]),
  P([("αυτί", "ear"), ("αυτή", "she, this (fem.)")],
    "**το αυτί** is the *ear*; **αυτή** *she, this (one)*. Both are pronounced *aftí*.",
    ex=[("Μου είπε κάτι στο αυτί.", "He whispered something in my ear."), ("Αυτή είναι η αδερφή μου.", "This is my sister.")],
    gaps=[("Με πονάει το ___ μου.", "αυτί", ["αυτή"], "My ear hurts.")]),
  P([("σύκο", "fig"), ("σήκω", "get up! (imperative)")],
    "**το σύκο** is a *fig*; **σήκω!** is the imperative of σηκώνομαι: *get up!* The same sound, a world apart: the fig tree is **η συκιά**.",
    ex=[("Σήκω, άργησες!", "Get up, you're late!"), ("Τα σύκα είναι ώριμα τον Αύγουστο.", "Figs are ripe in August.")],
    gaps=[("___, έχουμε σχολείο!", "Σήκω", ["Σύκο"], "Get up, we've got school!")]),
  P([("τύχη", "luck, fate"), ("τείχη", "walls (city)")],
    "**η τύχη** is *luck* (καλή τύχη! *good luck!*); **τα τείχη** are city walls (plural of τείχος).",
    ex=[("Καλή τύχη στις εξετάσεις!", "Good luck in the exams!")],
    gaps=[("Είχαμε ___ και βρήκαμε θέση για να παρκάρουμε.", "τύχη", ["τείχη"], "We were lucky and found a parking space.")]),
  P([("κόμμα", "party; comma"), ("κώμα", "coma")],
    "**το κόμμα** is a party or a comma; **το κώμα** a *coma*. Only the ο/ω tells them apart.",
    ex=[("Ο ασθενής βρίσκεται σε κώμα.", "The patient is in a coma.")],
    gaps=[("Μετά το ατύχημα έμεινε σε ___ για δύο μέρες.", "κώμα", ["κόμμα"], "After the accident he was in a coma for two days.")]),
  P([("ψιλός", "fine, thin"), ("ψηλός", "tall, high")],
    "**ψηλός** is *tall, high* (ψηλό βουνό); **ψιλός** is *fine, thin* (ψιλή βροχή *drizzle*, ψιλά *small change*, ψιλοκομμένο *finely chopped*). The colloquial prefix **ψιλο-** *a bit* comes from ψιλός.",
    ex=[("Ο αδερφός μου είναι πολύ ψηλός.", "My brother is very tall."), ("Έχεις ψιλά για το λεωφορείο;", "Do you have change for the bus?")],
    gaps=[("Ο Όλυμπος είναι το πιο ___ βουνό της Ελλάδας.", "ψηλό", ["ψιλό"], "Olympus is the highest mountain in Greece."), ("Έπεφτε ___ βροχή όλο το πρωί.", "ψιλή", ["ψηλή"], "A fine drizzle fell all morning.")]),
  P([("πάλι", "again"), ("πάλη", "wrestling; struggle")],
    "**πάλι** is *again* (= ξανά); **η πάλη** is *wrestling* (ελληνορωμαϊκή πάλη *Greco-Roman wrestling*) and a *struggle* (ταξική πάλη *class struggle*).",
    ex=[("Πάλι άργησες!", "You're late again!"), ("Κέρδισε μετάλλιο στην πάλη.", "He won a medal in wrestling.")],
    gaps=[("Πού είναι ___ τα κλειδιά μου;", "πάλι", ["πάλη"], "Where are my keys again?")]),
  P([("χείρα", "hand (formal)"), ("χήρα", "widow")],
    "**η χήρα** is a *widow* (ο χήρος *widower*); **η χείρα** is the learned word for *hand*, alive in compounds (**χειρουργός**, **εγχειρίδιο**) and in **χειραψία** *handshake*.",
    ex=[("Έμεινε χήρα στα σαράντα της.", "She was widowed at forty."), ("Αντάλλαξαν μια θερμή χειραψία.", "They exchanged a warm handshake.")],
    gaps=[("Η γειτόνισσά μας είναι ___ εδώ και χρόνια.", "χήρα", ["χείρα"], "Our neighbour has been a widow for years.")]),
  P([("κλίμα", "climate"), ("κλήμα", "vine")],
    "**το κλίμα** is *climate* (and *atmosphere*: καλό κλίμα στην ομάδα); **το κλήμα** is a *grapevine* (κληματαριά *vine arbour*).",
    ex=[("Η Κρήτη έχει ήπιο κλίμα.", "Crete has a mild climate."), ("Τα κλήματα φορτώθηκαν σταφύλια.", "The vines are heavy with grapes.")],
    gaps=[("Η κλιματική αλλαγή επηρεάζει το ___ της Μεσογείου.", "κλίμα", ["κλήμα"], "Climate change is affecting the Mediterranean climate.")]),
  P([("λείπω", "be absent, be missing"), ("λίπος", "fat")],
    "**λείπω** is *be away, be missing*: **μου λείπεις** *I miss you* (literally *you are missing to me*). **το λίπος** is *fat* (ζωικό λίπος). Both pronounced with *i*.",
    ex=[("Μου λείπεις πολύ.", "I miss you a lot."), ("Αυτό το κρέας έχει πολύ λίπος.", "This meat is very fatty.")],
    gaps=[("Ο διευθυντής ___ σήμερα, είναι σε σεμινάριο.", "λείπει", ["λίπει"], "The manager is away today, he's at a seminar."), ("Το κρέας έχει πολύ ___, δεν το τρώω.", "λίπος", ["λείπος"], "The meat is very fatty, I won't eat it.")]),
 ]),

dict(id="verb-pairs", el="Ρήματα που μπερδεύονται", title="Verbs that learners mix up", level="A1–B2",
 intro=["Verb pairs that look or sound alike, or that split one English verb in two. Many are pairs of *go* and *make go*: **μπαίνω / βάζω**, **βγαίνω / βγάζω**, **ανεβαίνω / ανεβάζω**."],
 pairs=[
  P([("βάζω", "put (in, on)"), ("βγάζω", "take out, take off")],
    "**βάζω** is *put in/on* (βάζω το παλτό *put on my coat*); **βγάζω** is the opposite, *take out/off* (βγάζω τα παπούτσια *take off my shoes*, βγάζω φωτογραφία *take a photo*, βγάζω λεφτά *earn money*). One letter, opposite meanings.",
    ex=[("Βγάλε τα παπούτσια σου πριν μπεις.", "Take your shoes off before you come in."), ("Βάλε το γάλα στο ψυγείο.", "Put the milk in the fridge.")],
    gaps=[("Κάνει κρύο, ___ το μπουφάν σου.", "βάλε", ["βγάλε"], "It's cold, put your jacket on."), ("Μπορείς να μας ___ μια φωτογραφία;", "βγάλεις", ["βάλεις"], "Could you take a photo of us?")]),
  P([("μπαίνω", "go in, get in"), ("βγαίνω", "go out, get out")],
    "**μπαίνω** *go in*, **βγαίνω** *go out* (also *go out* socially, and *come out*: βγήκε το βιβλίο *the book came out*). Their causative partners are **βάζω** and **βγάζω**.",
    ex=[("Μπες μέσα, βρέχει.", "Come inside, it's raining."), ("Βγαίνουμε απόψε;", "Are we going out tonight?")],
    gaps=[("Δεν ___ ποτέ χωρίς ομπρέλα τον χειμώνα.", "βγαίνω", ["μπαίνω"], "I never go out without an umbrella in winter.")]),
  P([("ανεβαίνω", "go up, climb"), ("ανεβάζω", "raise, take up; upload")],
    "**ανεβαίνω** is intransitive: *I go up*. **ανεβάζω** takes an object: *raise, carry up, put on (a play), upload*. The same pattern: **κατεβαίνω** *go down* / **κατεβάζω** *lower, take down, download*.",
    ex=[("Ανεβαίνω με τα πόδια, όχι με το ασανσέρ.", "I walk up, I don't take the lift."), ("Ανέβασε τις φωτογραφίες στο ίντερνετ.", "She uploaded the photos to the internet.")],
    gaps=[("Μπορείς να ___ τη βαλίτσα στον τρίτο;", "ανεβάσεις", ["ανέβεις"], "Can you take the suitcase up to the third floor?"), ("Το βράδυ ___ την ταινία από το ίντερνετ.", "κατέβασα", ["κατέβηκα"], "In the evening I downloaded the film.")]),
  P([("φέρνω", "bring"), ("παίρνω", "take, get")],
    "**φέρνω** is movement towards the speaker (*bring*), **παίρνω** is *take, get, receive, buy*. **Πάρε τηλέφωνο** is *call*; **φέρε μου** *bring me*.",
    ex=[("Φέρε μου ένα ποτήρι νερό, σε παρακαλώ.", "Bring me a glass of water, please."), ("Πάρε μαζί σου ομπρέλα.", "Take an umbrella with you.")],
    gaps=[("Θα ___ το κρασί στο πάρτι;", "φέρεις", ["πάρεις"], "Will you bring the wine to the party?"), ("Πρέπει να ___ το λεωφορείο των οχτώ.", "πάρω", ["φέρω"], "I have to take the eight o'clock bus.")]),
  P([("ρωτάω", "ask (a question)"), ("ζητάω", "ask for, request")],
    "English *ask* is two verbs in Greek: **ρωτάω / ρωτώ** asks a question (ρώτησέ τον πού μένει), **ζητάω / ζητώ** asks for something (ζήτησε τον λογαριασμό).",
    ex=[("Ρώτησα τον σερβιτόρο αν έχουν ψάρι.", "I asked the waiter whether they had fish."), ("Ζήτησα τον λογαριασμό.", "I asked for the bill.")],
    gaps=[("Μπορώ να σε ___ κάτι;", "ρωτήσω", ["ζητήσω"], "Can I ask you something?"), ("Του ___ βοήθεια αλλά δεν ήρθε.", "ζήτησα", ["ρώτησα"], "I asked him for help but he didn't come.")]),
  P([("ξέρω", "know (a fact); know how"), ("γνωρίζω", "know, be acquainted with; meet")],
    "**ξέρω** is *know* a fact or a skill (ξέρω να κολυμπάω). **γνωρίζω** is *know, be acquainted with* a person or place, and in the aorist *meet for the first time*: **χάρηκα που σε γνώρισα** *nice to have met you*. In formal Greek γνωρίζω also covers *know a fact*.",
    ex=[("Ξέρεις πού είναι το μουσείο;", "Do you know where the museum is?"), ("Πού γνωριστήκατε;", "Where did you meet?")],
    gaps=[("Χάρηκα πολύ που σας ___.", "γνώρισα", ["ήξερα"], "Very nice to have met you."), ("Δεν ___ τι ώρα κλείνει το μαγαζί.", "ξέρω", ["γνωρίζω"], "I don't know what time the shop closes.")]),
  P([("μπορώ", "can, be able"), ("ξέρω να", "know how to")],
    "**μπορώ** is *can* in the sense of ability or permission at a given moment; **ξέρω να** is *know how to*, a learned skill. *I can swim* (I have learned) is **ξέρω να κολυμπάω**; *I can't swim today* (I'm ill) is **δεν μπορώ να κολυμπήσω σήμερα**.",
    ex=[("Ξέρεις να οδηγείς;", "Can you drive? (Do you know how?)"), ("Μπορείς να με πας στο αεροδρόμιο;", "Can you take me to the airport?")],
    gaps=[("Δεν ___ να κολυμπήσω σήμερα, έχω πυρετό.", "μπορώ", ["ξέρω"], "I can't swim today, I have a temperature."), ("Η κόρη μου ___ να διαβάζει από τεσσάρων χρονών.", "ήξερε", ["μπορούσε"], "My daughter knew how to read from the age of four.")]),
  P([("θυμάμαι", "remember"), ("θυμίζω", "remind")],
    "**θυμάμαι** *remember* (deponent: θυμήθηκα *I remembered*); **θυμίζω** *remind*: *θύμισέ μου να…* remind me to…; *μου θυμίζει* *it reminds me of*.",
    ex=[("Δεν θυμάμαι πού πάρκαρα.", "I don't remember where I parked."), ("Θύμισέ μου να πάρω τη γιαγιά τηλέφωνο.", "Remind me to call grandma.")],
    gaps=[("Αυτό το τραγούδι μου ___ το καλοκαίρι στη Νάξο.", "θυμίζει", ["θυμάται"], "This song reminds me of the summer on Naxos.")]),
  P([("δανείζω", "lend"), ("δανείζομαι", "borrow")],
    "Active **δανείζω** is *lend*; the passive form **δανείζομαι** is *borrow*. Ask **μου δανείζεις…;** *can you lend me…?*",
    ex=[("Μου δανείζεις το ποδήλατό σου;", "Will you lend me your bike?"), ("Δανείστηκα λεφτά από την τράπεζα.", "I borrowed money from the bank.")],
    gaps=[("___ ένα βιβλίο από τη βιβλιοθήκη.", "Δανείστηκα", ["Δάνεισα"], "I borrowed a book from the library.")]),
  P([("αφήνω", "leave (something, someone); let"), ("φεύγω", "leave, go away")],
    "**φεύγω** is *leave* with no object: I go away. **αφήνω** has an object: *leave something behind, leave someone* and *let*: **άφησέ με** *let me (be)*.",
    ex=[("Φεύγω στις πέντε.", "I'm leaving at five."), ("Άφησα το κινητό στο σπίτι.", "I left my phone at home.")],
    gaps=[("Το τρένο ___ σε δέκα λεπτά.", "φεύγει", ["αφήνει"], "The train leaves in ten minutes."), ("Μην ___ την πόρτα ανοιχτή.", "αφήνεις", ["φεύγεις"], "Don't leave the door open.")]),
  P([("χάνω", "lose; miss (a bus)"), ("λείπω", "be missing; be away"), ("μου λείπει", "I miss (someone)")],
    "**χάνω** is *lose* (keys, a match) and *miss* a bus or a chance. To *miss a person* is **μου λείπει**, with the person as subject: **μου λείπεις** *I miss you*. **Χάθηκα** *I got lost*.",
    ex=[("Έχασα το λεωφορείο.", "I missed the bus."), ("Μου λείπει η Ελλάδα.", "I miss Greece.")],
    gaps=[("Μου ___ πολύ οι φίλοι μου.", "λείπουν", ["χάνουν"], "I miss my friends a lot."), ("Βιάσου, θα ___ την πτήση!", "χάσουμε", ["λείψουμε"], "Hurry, we'll miss the flight!")]),
  P([("μιλάω", "speak, talk"), ("λέω", "say, tell")],
    "**μιλάω** *speak, talk* (μιλάω ελληνικά, μιλάω με τη μητέρα μου); **λέω** *say, tell* something: **λέω την αλήθεια**, **τι λες;** *what are you saying?*. *Tell someone* is **λέω σε κάποιον** or with a weak pronoun: **μου είπε** *he told me*.",
    ex=[("Μιλάς ελληνικά;", "Do you speak Greek?"), ("Τι είπε ο γιατρός;", "What did the doctor say?")],
    gaps=[("Μου ___ ότι θα αργήσει.", "είπε", ["μίλησε"], "He told me he'd be late.")]),
  P([("βλέπω", "see; watch"), ("κοιτάζω", "look at")],
    "**βλέπω** is *see* and *watch* (βλέπω τηλεόραση); **κοιτάζω / κοιτάω** is *look at* deliberately: **κοίτα!** *look!*, and also *check, see to*: **κοίτα να…** *make sure you…*",
    ex=[("Κοίτα τι ωραίο ηλιοβασίλεμα!", "Look what a beautiful sunset!"), ("Είδες την ταινία;", "Did you see the film?")],
    gaps=[("Μη με ___ έτσι!", "κοιτάς", ["βλέπεις"], "Don't look at me like that!")]),
  P([("μαθαίνω", "learn; find out"), ("διδάσκω", "teach")],
    "**μαθαίνω** is *learn*, *find out* and, colloquially, *teach someone something*: **μου έμαθε κολύμπι** *he taught me to swim*. The proper verb for teaching is **διδάσκω**: **διδάσκει ιστορία** *she teaches history*.",
    ex=[("Μαθαίνω ελληνικά εδώ και δύο χρόνια.", "I've been learning Greek for two years."), ("Διδάσκει φιλοσοφία στο πανεπιστήμιο.", "He teaches philosophy at the university.")],
    gaps=[("Πώς ___ τα νέα;", "έμαθες", ["δίδαξες"], "How did you find out the news?")]),
  P([("περνάω", "pass; spend (time)"), ("ξοδεύω", "spend (money)")],
    "*Spend* is two verbs: time is **περνάω** (περάσαμε υπέροχα *we had a wonderful time*), money is **ξοδεύω**. **Περνάω** also means *pass* (an exam, by a place, the salt).",
    ex=[("Πώς πέρασες στις διακοπές;", "How were your holidays?"), ("Ξόδεψα όλα τα λεφτά μου.", "I spent all my money.")],
    gaps=[("___ το καλοκαίρι στην Κρήτη.", "Περάσαμε", ["Ξοδέψαμε"], "We spent the summer in Crete."), ("Πόσα ___ στα ψώνια;", "ξόδεψες", ["πέρασες"], "How much did you spend on shopping?")]),
  P([("ακούω", "hear; listen"), ("ακούγομαι", "sound, be heard")],
    "**ακούω** is *hear* and *listen to*; **ακούγομαι** is *sound, be heard*: **ακούγεται ωραίο** *it sounds nice*, **δεν ακούγεσαι** *I can't hear you* (on the phone: *you're not coming through*).",
    ex=[("Ακούγεται καλή ιδέα.", "That sounds like a good idea."), ("Ακούω μουσική όταν δουλεύω.", "I listen to music when I work.")],
    gaps=[("Η πρότασή σου ___ ενδιαφέρουσα.", "ακούγεται", ["ακούει"], "Your proposal sounds interesting.")]),
 ]),

dict(id="near-synonyms", el="Συνώνυμα με διαφορά", title="Near-synonyms: which word for which job", level="A2–C1",
 intro=["Words that English translates the same way but Greek keeps apart. Choosing the right one is what makes Greek sound natural at B2 and above."],
 pairs=[
  P([("καιρός", "weather; time (a while)"), ("χρόνος", "time (abstract); year"), ("ώρα", "hour; time (on the clock)"), ("φορά", "time (occurrence)")],
    "English *time* is four words. **ώρα** is clock time (*τι ώρα είναι;*, *είναι ώρα να…*); **χρόνος** is time as a quantity (*δεν έχω χρόνο*) and *year*; **καιρός** is *weather* and *a long time* (*πάει καιρός* it's been a while, *από καιρό σε καιρό* from time to time); **φορά** counts occurrences (*τρεις φορές*).",
    ex=[("Δεν έχω χρόνο σήμερα.", "I don't have time today."), ("Τι ώρα ξεκινάει η ταινία;", "What time does the film start?"), ("Έχουμε καιρό να τα πούμε!", "We haven't spoken for ages!"), ("Είναι η πρώτη φορά που έρχομαι.", "It's the first time I've come.")],
    gaps=[("Τι ___ κάνει αύριο στην Αθήνα;", "καιρό", ["χρόνο", "ώρα"], "What's the weather like in Athens tomorrow?"),
          ("Συγγνώμη, δεν έχω ___ να σου μιλήσω τώρα.", "χρόνο", ["καιρό", "φορά"], "Sorry, I don't have time to talk to you now."),
          ("Ήρθε δύο ___ αλλά δεν σε βρήκε.", "φορές", ["ώρες", "καιρούς"], "He came twice but didn't find you.")]),
  P([("νέος", "young; new (formal)"), ("καινούργιος", "new (brand new)")],
    "**καινούργιος** is *new* as opposed to used: a new car, new shoes. **νέος** is *young* (οι νέοι *young people*) and also *new* in the sense *recent, another*: **νέα κυβέρνηση**, **νέος νόμος**, **τα νέα** *the news*.",
    ex=[("Αγόρασα καινούργια παπούτσια.", "I bought new shoes."), ("Οι νέοι φεύγουν στο εξωτερικό.", "Young people are leaving for abroad.")],
    gaps=[("Το αυτοκίνητο είναι ___, το πήραμε την περασμένη εβδομάδα.", "καινούργιο", ["νέο"], "The car is new, we got it last week."), ("Η ___ γενιά μιλάει καλά αγγλικά.", "νέα", ["καινούργια"], "The young generation speaks good English.")]),
  P([("παλιός", "old (not new); former"), ("γέρος / ηλικιωμένος", "old (of people)"), ("αρχαίος", "ancient")],
    "Things are **παλιός** (παλιό σπίτι), and so are long-standing friends (**παλιός φίλος**). Old people are **ηλικιωμένοι** (polite) or **γέροι** (blunt). Antiquity is **αρχαίος**: the ancient Greeks are **οι αρχαίοι Έλληνες**, never οι παλιοί Έλληνες.",
    ex=[("Μένουμε σε ένα παλιό σπίτι στην Πλάκα.", "We live in an old house in Plaka."), ("Βοήθησε μια ηλικιωμένη κυρία να περάσει τον δρόμο.", "He helped an elderly lady cross the road.")],
    gaps=[("Το θέατρο της Επιδαύρου είναι ___.", "αρχαίο", ["παλιό", "γέρικο"], "The theatre of Epidaurus is ancient."), ("Είναι ένας ___ φίλος από το σχολείο.", "παλιός", ["αρχαίος", "ηλικιωμένος"], "He's an old friend from school.")]),
  P([("χαρούμενος", "cheerful, glad"), ("ευτυχισμένος", "happy (deeply)"), ("ευχαριστημένος", "satisfied, pleased")],
    "**χαρούμενος** is *glad, cheerful* in the moment; **ευτυχισμένος** is *happy* in a deep, lasting way (ευτυχισμένο το νέο έτος!); **ευχαριστημένος** is *satisfied, pleased with something*.",
    ex=[("Είμαι πολύ ευχαριστημένος από το ξενοδοχείο.", "I'm very pleased with the hotel."), ("Ζουν ευτυχισμένοι στο νησί.", "They live happily on the island.")],
    gaps=[("Είστε ___ από την εξυπηρέτηση;", "ευχαριστημένοι", ["ευτυχισμένοι", "χαρούμενοι"], "Are you satisfied with the service?")]),
  P([("νομίζω", "think, believe (opinion)"), ("σκέφτομαι", "think (about), consider"), ("πιστεύω", "believe")],
    "**νομίζω ότι** gives an opinion (*I think that*); **σκέφτομαι** is the activity of thinking (*τι σκέφτεσαι;* what are you thinking about?) and *consider doing* (σκέφτομαι να…); **πιστεύω** is *believe* (in God, in someone) and a slightly firmer *I think*.",
    ex=[("Νομίζω ότι θα βρέξει.", "I think it's going to rain."), ("Σκέφτομαι να αλλάξω δουλειά.", "I'm thinking of changing jobs.")],
    gaps=[("___ ότι έχεις δίκιο.", "Νομίζω", ["Σκέφτομαι"], "I think you're right."), ("Τι ___ να κάνεις το καλοκαίρι;", "σκέφτεσαι", ["νομίζεις"], "What are you thinking of doing in the summer?")]),
  P([("μένω", "stay; live (somewhere)"), ("ζω", "live, be alive")],
    "*Where do you live?* is **πού μένεις;**: μένω is *live at an address*. **ζω** is *be alive, live a life* (ζει ακόμα; *is he still alive?*, ζω στην Ελλάδα εδώ και δέκα χρόνια *I've been living in Greece for ten years*, both fine).",
    ex=[("Μένω στο Παγκράτι.", "I live in Pangrati."), ("Ο παππούς μου ζει ακόμα.", "My grandfather is still alive.")],
    gaps=[("Σε ποιο ξενοδοχείο ___;", "μένετε", ["ζείτε"], "Which hotel are you staying at?")]),
  P([("δουλειά", "job; work (everyday)"), ("εργασία", "work (formal); assignment"), ("έργο", "work (of art); project; film")],
    "**δουλειά** is your job and work in everyday speech (*πάω για δουλειά*); **εργασία** is the formal word (*συνθήκες εργασίας* working conditions) and a school or university *assignment*; **έργο** is a *work* (of art, literature), a public *project* (δημόσια έργα *public works*) and a *film, play* (*τι έργο παίζει;* what's on?).",
    ex=[("Βρήκε δουλειά σε μια τράπεζα.", "She found a job at a bank."), ("Πρέπει να παραδώσω την εργασία αύριο.", "I have to hand in the assignment tomorrow.")],
    gaps=[("Ποιο είναι το πιο γνωστό ___ του Καζαντζάκη;", "έργο", ["εργασία", "δουλειά"], "What is Kazantzakis's best-known work?"), ("Τι ώρα σχολάς από τη ___;", "δουλειά", ["εργασία", "έργο"], "What time do you finish work?")]),
  P([("άνθρωπος", "person, human being"), ("άτομο", "individual, person (counting)"), ("κόσμος", "people (a crowd)")],
    "**άνθρωπος** is a human being (καλός άνθρωπος); **άτομο** counts people (*τραπέζι για τέσσερα άτομα* a table for four) and is the neutral *individual*; **κόσμος** (singular!) is *people* in general or a crowd: *είχε πολύ κόσμο*.",
    ex=[("Ένα τραπέζι για δύο άτομα, παρακαλώ.", "A table for two, please."), ("Στη λαϊκή είχε πολύ κόσμο.", "There were lots of people at the market.")],
    gaps=[("Η εκδρομή κοστίζει 30 ευρώ το ___.", "άτομο", ["άνθρωπο", "κόσμο"], "The trip costs 30 euros per person."), ("Γιατί έχει τόσο ___ σήμερα στο κέντρο;", "κόσμο", ["άτομο", "άνθρωπο"], "Why are there so many people in the centre today?")]),
  P([("ταξίδι", "trip, journey"), ("εκδρομή", "excursion, outing"), ("διαδρομή", "route, ride")],
    "**ταξίδι** is a journey of any length (*καλό ταξίδι!*); **εκδρομή** is a day trip or outing (σχολική εκδρομή); **διαδρομή** is the *route* and the ride itself (*η διαδρομή κρατάει δύο ώρες* the ride takes two hours).",
    ex=[("Πήγαμε εκδρομή στους Δελφούς.", "We went on an outing to Delphi."), ("Η διαδρομή με το πλοίο είναι πανέμορφη.", "The boat ride is gorgeous.")],
    gaps=[("Την Κυριακή το σχολείο οργανώνει ___ στο Σούνιο.", "εκδρομή", ["διαδρομή", "ταξίδι"], "On Sunday the school is organising a trip to Sounion.")]),
  P([("χώρα", "country (territory)"), ("κράτος", "state"), ("έθνος", "nation"), ("πατρίδα", "homeland")],
    "**χώρα** is the country as a place (*ταξιδεύω σε άλλες χώρες*); **κράτος** the state and its institutions (*το κράτος πρόνοιας* the welfare state); **έθνος** the nation as a people with a shared identity; **πατρίδα** the homeland you belong to.",
    ex=[("Η Ελλάδα είναι μια μικρή χώρα.", "Greece is a small country."), ("Το κράτος πρέπει να στηρίξει τις οικογένειες.", "The state must support families.")],
    gaps=[("Μετά από είκοσι χρόνια στο εξωτερικό, γύρισε στην ___ του.", "πατρίδα", ["κράτος", "έθνος"], "After twenty years abroad, he returned to his homeland.")]),
  P([("τελειώνω", "finish, end"), ("σταματώ", "stop"), ("κόβω", "cut; give up (a habit)")],
    "**τελειώνω** is *finish* (a task) or *come to an end*; **σταματώ** is *stop* (an action or a vehicle); **κόβω** is *cut* and, of habits, *quit*: **έκοψα το τσιγάρο** *I quit smoking*.",
    ex=[("Σταμάτα να φωνάζεις!", "Stop shouting!"), ("Έκοψε τη ζάχαρη για υγεία.", "He cut out sugar for his health.")],
    gaps=[("Το λεωφορείο ___ μπροστά στο μουσείο.", "σταματάει", ["τελειώνει", "κόβει"], "The bus stops in front of the museum."), ("Πριν από τρία χρόνια ___ το κάπνισμα.", "έκοψα", ["τελείωσα", "έκλεισα"], "Three years ago I quit smoking.")]),
  P([("μικρός", "small, young"), ("λίγος", "little, few (amount)")],
    "**μικρός** is size and age (*μικρό σπίτι*, *ο μικρός μου αδερφός*); **λίγος** is quantity (*λίγο νερό*, *λίγοι άνθρωποι*). *A little* water is **λίγο νερό**, never μικρό νερό.",
    ex=[("Θέλω λίγο ψωμί.", "I'd like a little bread."), ("Το διαμέρισμα είναι μικρό αλλά άνετο.", "The flat is small but comfortable.")],
    gaps=[("Ήρθαν πολύ ___ φοιτητές στη διάλεξη.", "λίγοι", ["μικροί"], "Very few students came to the lecture.")]),
 ]),

dict(id="small-words", el="Μικρές λέξεις, μεγάλες διαφορές", title="Small words with big differences", level="A2–B2",
 intro=["Function words are short, frequent and easy to mix up: the accented and unaccented **πού / που**, **πώς / πως**, **ό,τι / ότι**, the two negatives **δεν / μη**, and the time adverbs **πια, ακόμα, ήδη**."],
 pairs=[
  P([("πού", "where?"), ("που", "who, which, that (relative)")],
    "**πού;** with an accent asks *where?*; **που** without an accent is the relative pronoun *who / which / that* (ο άνθρωπος που είδα) and a conjunction (*χαίρομαι που ήρθες* I'm glad you came).",
    ex=[("Πού μένεις;", "Where do you live?"), ("Η ταινία που είδαμε ήταν καλή.", "The film we saw was good.")],
    gaps=[("___ είναι η στάση του μετρό;", "Πού", ["Που"], "Where is the metro stop?"), ("Ο φίλος ___ σου είπα είναι γιατρός.", "που", ["πού"], "The friend I told you about is a doctor.")]),
  P([("πώς", "how?"), ("πως", "that (= ότι)")],
    "**πώς;** asks *how?* (πώς είσαι;); **πως** without an accent is *that* after verbs of saying and thinking, a less formal **ότι**: *λέει πως θα έρθει*.",
    ex=[("Πώς το λένε αυτό στα ελληνικά;", "How do you say this in Greek?"), ("Μου είπε πως είναι άρρωστος.", "He told me that he's ill.")],
    gaps=[("___ πάμε στο λιμάνι;", "Πώς", ["Πως"], "How do we get to the port?"), ("Νομίζω ___ έχεις δίκιο.", "πως", ["πώς"], "I think that you're right.")]),
  P([("ότι", "that (conjunction)"), ("ό,τι", "whatever, anything that")],
    "**ότι** is *that* (ξέρω ότι…); **ό,τι** with a comma is *whatever*: **ό,τι θέλεις** *whatever you like*, **ό,τι καλύτερο** *all the best*. The comma is part of the spelling.",
    ex=[("Ξέρω ότι είσαι κουρασμένος.", "I know that you're tired."), ("Πάρε ό,τι θέλεις από το ψυγείο.", "Take whatever you want from the fridge.")],
    gaps=[("Σου εύχομαι ___ καλύτερο!", "ό,τι", ["ότι"], "I wish you all the best!"), ("Μου είπε ___ θα αργήσει.", "ότι", ["ό,τι"], "He told me that he'd be late.")]),
  P([("δεν", "not (with statements)"), ("μη(ν)", "not, don't (with να, imperatives, wishes)")],
    "**δεν** negates statements and questions (δεν ξέρω); **μη(ν)** negates after **να**, in prohibitions (**μην το κάνεις!** *don't do it!*), with participles (**μη καπνιστές** *non-smokers*) and after verbs of fearing (φοβάμαι μην…).",
    ex=[("Δεν θέλω καφέ.", "I don't want coffee."), ("Μην ανησυχείς!", "Don't worry!")],
    gaps=[("Σου είπα να ___ αργήσεις!", "μην", ["δεν"], "I told you not to be late!"), ("___ καταλαβαίνω τι λες.", "Δεν", ["Μην"], "I don't understand what you're saying.")]),
  P([("πια", "any more, no longer; now"), ("ακόμα", "still; yet; even"), ("ήδη", "already")],
    "**πια** with a negative is *no longer, not any more* (δεν μένει πια εδώ); **ακόμα** is *still* (ακόμα δουλεύει), *yet* with a negative (δεν ήρθε ακόμα) and *even* (ακόμα καλύτερα *even better*); **ήδη** is *already*.",
    ex=[("Δεν καπνίζω πια.", "I don't smoke any more."), ("Δεν έχει έρθει ακόμα.", "He hasn't come yet."), ("Έχω ήδη φάει.", "I've already eaten.")],
    gaps=[("Είναι δέκα και ο Νίκος κοιμάται ___.", "ακόμα", ["πια", "ήδη"], "It's ten o'clock and Nikos is still asleep."), ("Δεν δουλεύει ___ εκεί, άλλαξε δουλειά.", "πια", ["ακόμα", "ήδη"], "He doesn't work there any more, he changed jobs."), ("Μην αγοράσεις γάλα, έχω πάρει ___.", "ήδη", ["πια", "ακόμα"], "Don't buy milk, I've already got some.")]),
  P([("αν", "if; whether"), ("όταν", "when (whenever)")],
    "**αν** is a condition (*αν βρέξει, θα μείνουμε σπίτι*) or *whether* (*δεν ξέρω αν θα έρθει*); **όταν** is time (*όταν έρθεις, θα φάμε*). English speakers mix them in sentences about the future where *if* and *when* overlap.",
    ex=[("Αν έχεις χρόνο, πάρε με τηλέφωνο.", "If you have time, give me a call."), ("Όταν φτάσεις, πάρε με τηλέφωνο.", "When you arrive, give me a call.")],
    gaps=[("Ρώτησέ τον ___ θέλει να έρθει μαζί μας.", "αν", ["όταν"], "Ask him whether he wants to come with us."), ("___ ήμουν παιδί, ζούσαμε στη Λάρισα.", "Όταν", ["Αν"], "When I was a child, we lived in Larissa.")]),
  P([("για", "for; about"), ("για να", "in order to")],
    "**για** + noun is *for* or *about* (για σένα, ένα βιβλίο για την Κρήτη); **για να** + verb gives purpose: *in order to*. *I came to see you* is **ήρθα για να σε δω** (or simply **ήρθα να σε δω**), never *ήρθα για σε δω*.",
    ex=[("Αυτό το δώρο είναι για σένα.", "This present is for you."), ("Μαθαίνω ελληνικά για να μιλάω με την οικογένειά μου.", "I'm learning Greek to talk with my family.")],
    gaps=[("Πήγε στην Αθήνα ___ βρει δουλειά.", "για να", ["για"], "He went to Athens to find work.")]),
  P([("μέσα", "inside"), ("μέσω", "via, through")],
    "**μέσα** is *inside* (μέσα στο σπίτι); **μέσω** (+ genitive) is *via, by means of*: **μέσω Ρώμης** *via Rome*, **μέσω ίντερνετ** *online*.",
    ex=[("Πετάξαμε στην Αθήνα μέσω Φρανκφούρτης.", "We flew to Athens via Frankfurt."), ("Μπες μέσα!", "Come inside!")],
    gaps=[("Μπορείτε να πληρώσετε ___ τράπεζας.", "μέσω", ["μέσα"], "You can pay by bank transfer.")]),
  P([("αφού", "since, because; after"), ("αφότου", "ever since")],
    "**αφού** is *since (because)*, *after*, and an emphatic *but…!* (*αφού σου το είπα!* but I told you!); **αφότου** is *ever since*: *αφότου έφυγε, όλα άλλαξαν*.",
    ex=[("Αφού δεν θέλεις, δεν πειράζει.", "Since you don't want to, it doesn't matter."), ("Αφότου γεννήθηκε το μωρό, δεν κοιμόμαστε.", "Ever since the baby was born, we don't sleep.")],
    gaps=[("___ είσαι κουρασμένος, πήγαινε για ύπνο.", "Αφού", ["Αφότου"], "Since you're tired, go to bed.")]),
  P([("κιόλας", "already; too, even"), ("κι όλας", "(wrong spelling)")],
    "**κιόλας** is one word: *already* (*έφυγε κιόλας;* has he left already?) and, emphatically, *on top of that*: *και ακριβό κιόλας!* and expensive, too! **κι όλας** in two words is a common spelling mistake.",
    ex=[("Τελείωσες κιόλας;", "Have you finished already?")],
    gaps=[("Είναι ωραίο το φόρεμα, και φθηνό ___!", "κιόλας", ["κι όλας"], "The dress is lovely, and cheap too!")]),
 ]),

dict(id="number-gender", el="Γένος, πληθυντικός και λόγια διπλά", title="Gender, plurals and learned doublets that change the meaning", level="B1–C1",
 intro=["Some nouns change meaning with their plural or their gender; and many everyday words have a learned twin used in set phrases, signs and compounds. Mixing them up sounds odd at best and changes the meaning at worst."],
 pairs=[
  P([("οι χρόνοι", "times; tenses"), ("τα χρόνια", "years")],
    "**ο χρόνος** has two plurals. **οι χρόνοι** are *times, periods* and grammatical *tenses* (*οι χρόνοι του ρήματος*); **τα χρόνια** are *years*: *πριν από πολλά χρόνια*, *Χρόνια πολλά!*",
    ex=[("Μένω εδώ δέκα χρόνια.", "I've lived here for ten years."), ("Οι παρελθοντικοί χρόνοι είναι δύσκολοι.", "The past tenses are difficult.")],
    gaps=[("Πριν από πέντε ___ ζούσα στο Λονδίνο.", "χρόνια", ["χρόνους"], "Five years ago I lived in London.")]),
  P([("οι λόγοι", "reasons; speeches"), ("τα λόγια", "words (said), talk")],
    "**ο λόγος** also has two plurals: **οι λόγοι** *reasons, speeches* (για προσωπικούς λόγους *for personal reasons*); **τα λόγια** *words, what someone says*: **ωραία λόγια** *fine words*, **λόγια του αέρα** *empty talk*.",
    ex=[("Παραιτήθηκε για λόγους υγείας.", "He resigned for health reasons."), ("Δεν θέλω λόγια, θέλω πράξεις.", "I don't want words, I want action.")],
    gaps=[("Για ποιους ___ αποφάσισες να φύγεις;", "λόγους", ["λόγια"], "For what reasons did you decide to leave?"), ("Μη δίνεις σημασία στα ___ του.", "λόγια", ["λόγους"], "Don't pay attention to what he says.")]),
  P([("ο όρος", "term; condition"), ("το όρος", "mountain")],
    "**ο όρος** (masculine) is a *term, condition* (όροι χρήσης *terms of use*, με τον όρο ότι *on condition that*); **το όρος** (neuter, plural **τα όρη**) is a *mountain*, now mostly in names: **το Άγιον Όρος** *Mount Athos*.",
    ex=[("Δεν δέχομαι αυτούς τους όρους.", "I don't accept these terms."), ("Το Άγιον Όρος είναι μοναστική πολιτεία.", "Mount Athos is a monastic community.")],
    gaps=[("Διάβασε τους ___ πριν υπογράψεις.", "όρους", ["όρη"], "Read the terms before you sign.")]),
  P([("ο δεσμός", "bond, tie, relationship"), ("τα δεσμά", "chains, fetters")],
    "**ο δεσμός** is a *bond* (οικογενειακοί δεσμοί *family ties*) and a romantic *relationship* (έχει δεσμό *she's seeing someone*); its old plural **τα δεσμά** means *chains*, as in **Προμηθέας Δεσμώτης** *Prometheus Bound*.",
    ex=[("Έχουν στενούς δεσμούς με την Κύπρο.", "They have close ties with Cyprus."), ("Έσπασε τα δεσμά του.", "He broke his chains.")],
    gaps=[("Οι οικογενειακοί ___ είναι ισχυροί στην Ελλάδα.", "δεσμοί", ["δεσμά"], "Family ties are strong in Greece.")]),
  P([("νερό", "water (everyday)"), ("ύδωρ", "water (learned, in compounds and signs)")],
    "Say **νερό**; read **ύδωρ** and **υδρ-** on signs and in compounds: **μη πόσιμο ύδωρ** *non-drinking water*, **υδραυλικός** *plumber*. The same for **ψάρι / ιχθύς** (ιχθυοπωλείο), **ψωμί / άρτος** (αρτοποιείο), **κρασί / οίνος** (οινοποιείο).",
    ex=[("Ένα μπουκάλι νερό, παρακαλώ.", "A bottle of water, please."), ("Πήγαμε σε ένα οινοποιείο στη Νεμέα.", "We went to a winery in Nemea.")],
    gaps=[("Φέρε μου ένα ποτήρι ___.", "νερό", ["ύδωρ"], "Bring me a glass of water."), ("Το ψωμί το παίρνουμε από το ___ της γειτονιάς.", "αρτοποιείο", ["ιχθυοπωλείο"], "We get our bread from the neighbourhood bakery.")]),
  P([("σπίτι", "house, home"), ("οικία", "residence (official)")],
    "**σπίτι** is the everyday word; **οικία** appears in official language (*οικία του κατηγορουμένου* the defendant's residence) and in **κατ' οίκον** *at home* (κατ' οίκον νοσηλεία *home care*). **Πάω σπίτι** needs no article.",
    ex=[("Γυρνάω σπίτι στις έξι.", "I'm going home at six."), ("Η αστυνομία έκανε έρευνα στην οικία του.", "The police searched his residence.")],
    gaps=[("Είμαι κουρασμένος, πάω ___.", "σπίτι", ["οικία"], "I'm tired, I'm going home.")]),
  P([("ο χάρτης", "map"), ("ο χάρτης", "charter")],
    "**ο χάρτης** is a *map* and a *charter*: **ο Χάρτης των Ηνωμένων Εθνών** *the UN Charter*. Paper is **το χαρτί**; **τα χαρτιά** are *papers, documents* and also *playing cards*.",
    ex=[("Κοίτα στον χάρτη πού είμαστε.", "Look on the map where we are."), ("Παίζουμε χαρτιά τα βράδια.", "We play cards in the evenings.")],
    gaps=[("Φέρε όλα τα ___ για την εφορία.", "χαρτιά", ["χάρτες"], "Bring all the papers for the tax office.")]),
  P([("η φύλαξη", "guarding, custody"), ("η φυλακή", "prison")],
    "**φυλάω / φυλάγω** is *guard, keep*; **η φύλαξη** *safekeeping, custody* (φύλαξη αποσκευών *left luggage*); **η φυλακή** *prison* (literally *the guarding*), the inmate a **φυλακισμένος**, the guard a **φύλακας**.",
    ex=[("Καταδικάστηκε σε πέντε χρόνια φυλακή.", "He was sentenced to five years in prison."), ("Υπάρχει χώρος φύλαξης αποσκευών;", "Is there a left-luggage room?")],
    gaps=[("Ο ληστής πέρασε δέκα χρόνια στη ___.", "φυλακή", ["φύλαξη"], "The robber spent ten years in prison.")]),
 ]),
]
